pub fn admit_original_core_wire_delivery(cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{cx.original_source_parent()?.validate_borrowed_context(cx)?;if cx.original_source_epoch().is_none_or(|epoch|epoch==0){return Err(refused("core-wire delivery requires its actual actor epoch").into())}if cx.return_budget.as_ref().ok_or_else(||refused("core-wire delivery has no original Source budget"))?.get().core_delivery_ready()?{return Ok(true)}if cx.is_cancelled()||cx.should_yield(){return Ok(false)}let grant=cx.retained_grant();let fuel=cx.fuel_remaining();let turn=cx.return_budget.as_mut().ok_or_else(||refused("core-wire delivery has no original Source budget"))?.get_mut().switch_core_delivery(grant,fuel);let ready=turn.result?;if turn.work!=0{let posted=cx.consume_retained(P{copied_items:1,copied_bytes:OriginalReturnBudget::delivery_copy_bytes(),..Default::default()});cx.consume_fuel(turn.work);posted?}Ok(ready)}
