fn post_publisher(cx:&mut StepContext<'_>,progress:P,work:u64)->Result<(),OriginalTurnFailure>{let posted=cx.consume_retained(progress);cx.consume_fuel(work);if let Err(error)=posted{let b=cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut();let source=b.refusal();b.fence_publisher();let mut failure=OriginalTurnFailure::from(error);failure.context_refusal=source;return Err(failure)}if let Some(error)=cx.return_budget.as_ref().and_then(|b|b.get().refusal()){if let Some(b)=cx.return_budget.as_mut(){b.get_mut().fence_publisher()}return Err(error.into())}Ok(())}
pub fn admit_original_escrow_publisher(cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{cx.original_source_parent()?.validate_borrowed_context(cx)?;let budget=cx.return_budget.as_ref().ok_or_else(||refused(E::PUBLISHER_ABSENT))?.get();if budget.local_delivery(){return Err(refused("escrow publisher requires Core-wire delivery").into())}if budget.publisher_is_admitted(){if let Some(error)=budget.refusal(){return Err(error.into())}if !budget.publisher_is_ready(){return Err(refused("publisher placement fenced").into())}return Ok(true)}if !admit_original_return_table(cx)?{return Ok(false)}let(copy,capacity,work)=OriginalEscrowPublisher::birth_demand();let copy=copy+std::mem::size_of::<bool>();let budget=cx.return_budget.as_ref().ok_or_else(||refused(E::PUBLISHER_LOST))?.get();let(raw,fuel)=budget.raw_remaining()?;S(raw,fuel,1,copy,capacity,work,K::Publisher)?;if (if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.is_cancelled()||cx.should_yield()})||!cx.retained_recipient_is_admitted()||cx.retained_grant().maximum_copy_bytes<copy{return Ok(false)}cx.retained_progress().checked_add(P{copied_items:1,copied_bytes:copy,retained_capacity_bytes:capacity,..Default::default()})?;let grant=cx.retained_grant();let fuel=cx.fuel_remaining();let turn=cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut().admit_publisher(grant,fuel);let Some(progress)=turn.result?else{return Ok(false)};#[cfg(any(test,feature="testkit"))]crate::testkit::narrow_loan_receipt(cx);post_publisher(cx,progress,turn.work)?;Ok(true)}
/// 📤️ See `README.md`.
pub fn publish_original_escrow(cx:&mut StepContext<'_>,header:usize,expose:impl for<'loan> FnOnce(&'loan [u8])->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{
 let parent=cx.original_source_parent()?;parent.validate_borrowed_context(cx)?;let source_id=parent.source_identity()?;OriginalReturnSourceInput::capture(cx)?;if cx.original_source_epoch().is_none_or(|e|e==0){return Err(refused("Core epoch absent").into())}let grant=cx.retained_grant();let fuel=cx.fuel_remaining();let reserve=OriginalEscrowPublisher::core_wire_reserve(header)?;if grant.maximum_items<reserve.items||grant.maximum_copy_bytes<reserve.copy_bytes||grant.maximum_depth==0{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"Core wire reserve absent").into())}if fuel<reserve.work{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Core wire work absent").into())}cx.retained_progress().checked_add(P{copied_items:reserve.items,copied_bytes:reserve.copy_bytes,..Default::default()})?;
 let publication={let book=cx.return_budget.as_mut().ok_or_else(||refused("Core Source absent"))?.get_mut();let Some(publication)=book.publish_extent(source_id,header,grant,fuel)?else{return Ok(false)};publication};
 let d=publication.demand;post_publisher(cx,P{copied_items:d.items,copied_bytes:d.copy_bytes,..Default::default()},d.work)?;let result={let book=cx.return_budget.as_ref().ok_or_else(||refused("Core Source absent"))?.get();expose(book.borrowed_publication()?)};result?;Ok(true)
}
pub fn finish_original_header(cx:&mut StepContext<'_>,loan:&mut Option<semio_framework_job_return_escrow_publication::OriginalEscrowHeaderLoan>,returned:&mut Option<semio_framework_job_return_escrow_publication::OriginalEscrowHeaderReturned>,a:&crate::OriginalCallerReturnPlace,b:&crate::OriginalCallerReturnPlace,c:&crate::OriginalCallerReturnPlace)->Result<bool,OriginalTurnFailure>{
 let parent=cx.original_source_parent()?;parent.validate_borrowed_context(cx)?;let source=parent.source_identity()?;OriginalReturnSourceInput::capture(cx)?;if cx.original_source_epoch().is_none_or(|e|e==0)||std::ptr::eq(a,b)||std::ptr::eq(a,c)||std::ptr::eq(b,c)||loan.is_some()||returned.is_some(){return Err(refused("header custody changed").into())}let l=loan as *mut _ as usize;let r=returned as *mut _ as usize;a.qualify_sized(cx,l,std::mem::size_of_val(loan))?;b.qualify_sized(cx,l,std::mem::size_of_val(loan))?;c.qualify_sized(cx,r,std::mem::size_of_val(returned))?;if !a.capture_is_preissued()||!b.capture_is_preissued()||!c.capture_is_preissued(){return Err(refused("header permits absent").into())}if (if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.should_yield()||cx.is_cancelled()}){return Ok(false)}let grant=cx.retained_grant();let fuel=cx.fuel_remaining();let d=OriginalEscrowPublisher::header_loan_demand();if grant.maximum_items<d.items||grant.maximum_copy_bytes<d.copy_bytes||grant.maximum_depth==0||fuel<d.work{return Ok(false)}cx.retained_progress().checked_add(P{copied_items:d.items,copied_bytes:d.copy_bytes,..Default::default()})?;
 let ready=cx.return_budget.as_mut().ok_or_else(||refused(E::PUBLISHER_LOST))?.get_mut().finish_header(source,loan,grant,fuel)?;if !ready{return Ok(false)}let posted=cx.consume_retained(P{copied_items:d.items,copied_bytes:d.copy_bytes,..Default::default()});cx.consume_fuel(d.work);if let Err(error)=posted{let source=cx.return_budget.as_ref().and_then(|b|b.get().refusal());let mut failure=OriginalTurnFailure::from(error);failure.context_refusal=source;return Err(failure)}if let Some(error)=cx.return_budget.as_ref().and_then(|b|b.get().refusal()){return Err(error.into())}Ok(true)
}
pub fn admit_original_return_table(cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let parent=cx.original_source_parent()?;parent.validate_borrowed_context(cx)?;if cx.return_budget.as_ref().is_some_and(|budget|budget.get().table_is_admitted()){return Ok(true)}let bound=cx.return_budget.as_ref().is_some_and(|budget|budget.get().is_bound());let(copy,capacity,work)=OriginalReturnEscrowTable::birth_demand();let total=if bound{cx.return_budget.as_ref().ok_or_else(||refused("original return budget disappeared"))?.get().remaining()?.0}else{super::super::retained_remaining(cx.original_total_retained_grant(),super::super::retained_delta(cx.retained_progress(),cx.original_total_retained_start))};S(total,cx.original_total_fuel_remaining(),1+usize::from(!bound),copy,capacity,work+u64::from(!bound),K::Table)?;if !parent.admit_return_origin(cx)?||!bound{return Ok(false)}if (if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.is_cancelled()||cx.should_yield()})||!cx.retained_recipient_is_admitted(){return Ok(false)}let grant=cx.retained_grant();let fuel=cx.fuel_remaining();let turn=cx.return_budget.as_mut().ok_or_else(||refused("original return source budget disappeared"))?.get_mut().admit_table(grant,fuel);let Some(progress)=turn.result?else{return Ok(false)};let posted=cx.consume_retained(progress);cx.consume_fuel(turn.work);posted?;Ok(true)}
pub fn claim_original_return(cx:&mut StepContext<'_>,output:&mut Option<OriginalReturnClaimCredit>)->Result<bool,OriginalTurnFailure>{let destination=output as *mut _ as usize;claim_original_sized_return(cx,output,destination,0,0)}
pub fn claim_original_sized_return(cx:&mut StepContext<'_>,output:&mut Option<OriginalReturnClaimCredit>,destination:usize,copy_bytes:usize,metadata:usize)->Result<bool,OriginalTurnFailure>{
 cx.original_source_parent()?.validate_borrowed_context(cx)?;if let Some(credit)=output{let budget=cx.return_budget.as_ref().ok_or_else(||refused("cached original return claim lacks its genuine budget"))?.get();credit.validate_cached(budget,destination,copy_bytes)?;return Ok(true)}if let Some(b)=cx.return_budget.as_ref().filter(|b|b.get().table_is_admitted()){let(raw,fuel)=b.get().raw_remaining()?;let extra=2*M::UPDATE+M::FINAL+if b.get().local_delivery(){M::LOCAL_ACK}else{0};let needed=copy_bytes.checked_add(extra).and_then(|n|n.checked_add(original_return_claim_copy_bytes())).and_then(|n|n.checked_add(metadata)).ok_or_else(||refused("return claim copy overflow"))?;if raw.maximum_items<3||raw.maximum_depth==0||raw.maximum_copy_bytes<needed{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,E::CLAIM_OWNERSHIP).into())}if fuel<3{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original return claim exceeds its remaining lifetime work currency").into())}}if (if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.is_cancelled()||cx.should_yield()})||!cx.retained_recipient_is_admitted()||cx.retained_grant().maximum_items==0||cx.retained_grant().maximum_depth==0{return Ok(false)}if cx.return_budget.as_ref().is_none_or(|budget|!budget.get().table_is_admitted()){admit_original_return_table(cx)?;return Ok(false)}let full=cx.return_budget.as_ref().is_some_and(|budget|!budget.get().table_has_capacity());if full{let reclaim=cx.return_budget.as_ref().is_some_and(|budget|budget.get().table_has_reclaimable());if !reclaim||cx.retained_grant().maximum_copy_bytes<ORIGINAL_RETURN_ESCROW_RECLAIM_COPY_BYTES{return Ok(false)}if !cx.return_budget.as_mut().ok_or_else(||refused("original return budget disappeared"))?.get_mut().reclaim_one()?{return Ok(false)}let posted=cx.consume_retained(P{copied_items:1,copied_bytes:ORIGINAL_RETURN_ESCROW_RECLAIM_COPY_BYTES,..Default::default()});cx.consume_fuel(1);posted?;return Ok(false)}let row_copy=original_return_claim_copy_bytes().checked_add(metadata).ok_or_else(||refused("return metadata overflow"))?;let current_copy=cx.retained_grant().maximum_copy_bytes;let epoch=cx.original_source_epoch().unwrap_or(0);let budget=cx.return_budget.as_mut().ok_or_else(||refused("original return claim has no genuine source budget"))?;let(available,fuel)=budget.get().remaining()?;let extra=2*M::UPDATE+M::FINAL+if budget.get().local_delivery(){M::LOCAL_ACK}else{0};let needed=copy_bytes.checked_add(extra).and_then(|copy|copy.checked_add(row_copy)).ok_or_else(||refused("return claim copy overflow"))?;if available.maximum_items<3||available.maximum_copy_bytes<needed||fuel<3||current_copy<row_copy{return Ok(false)}let Some(credit)=budget.get_mut().claim(copy_bytes,destination,epoch)?else{return Ok(false)};*output=Some(credit);let progress=P{copied_items:1,copied_bytes:row_copy,..Default::default()};let posted=cx.consume_retained(progress);cx.consume_fuel(1);posted?;Ok(true)
}
pub fn receive_original_return_witness(cx:&mut StepContext<'_>,credit:&mut OriginalReturnClaimCredit,input:&mut Option<OriginalReturnWitness>)->Result<bool,OriginalTurnFailure>{
 let Some(witness)=input.as_mut()else{return Ok(true)};cx.original_source_parent()?.validate_borrowed_context(cx)?;let budget=cx.return_budget.as_ref().ok_or_else(||refused("source-paid return has no genuine receiving source"))?;let origin=budget.get().origin().ok_or_else(||refused("source-paid return receiver source is unbound"))?;if origin.source()!=witness.source()||origin.recipient()!=budget.get()as*const OriginalReturnBudget as usize||cx.original_clock_binding()!=Some(origin.clock())||!std::ptr::fn_addr_eq(cx.clock_source(),origin.now())||cx.original_absolute_deadline_us()!=origin.deadline(){return Err(refused("source-paid return requires its unchanged original receiving source").into())}

 if !witness.is_received(){cx.preflight_original_reserved_return(witness.progress(),witness.work())?;cx.return_budget.as_mut().ok_or_else(||ValueError::invariant("return_budget absent"))?.get_mut().redeem(credit,witness)?;cx.receive_original_reserved_return(witness.progress(),witness.work())?}
 cx.return_budget.as_mut().ok_or_else(||refused("original return source budget disappeared"))?.get_mut().finish_received(credit,witness)?;input.take();Ok(true)
}
